function V = run_replication(stages, outRoot)
%% Regenerate the empirical results into a fresh folder and verify them against results/.
%
%   V = run_replication()                        % default stages (about 1.5 h, base MATLAB)
%   V = run_replication({'empirical','verify'})  % selected stages
%   V = run_replication([], 'D:/scratch/rep')    % other output folder
%
% Every stage recomputes from data/ into outRoot (default <project>/results_replication,
% not tracked) through SDF_RESULTS_ROOT, so each stage reads the outputs regenerated by
% the stages before it. A stage whose outputs already exist in outRoot is resumed or
% skipped; the finalized outputs in <project>/results are only read (by 'verify').
%
% Stages, in order (default: all except 'cv', 'lw' and 'data'):
%   data       rebuild forwards and panels from raw WRDS files (data_reconstructed/raw;
%              writes data_reconstructed/, never data/)                          ~3 min
%   empirical  eff_dim fits, the 54 shape tests per maturity, conditional SDF figures ~15 min
%   cv         CV robustness fits and shape tests (grid search)                  ~30 min
%   noncrisis  non-crisis eff_dim fits (Table 4.1, Panel B)                      ~1 min
%   oos        expanding-window OOS fits (882 windows), the alternative information
%              rule, daily 2023-10-19 exclusion, OOS tables                       ~45 min
%   effdim     effective-dimension target 0.5x / 1x / 2x (monthly, IA table)     ~10 min
%   lw         Ledoit-Wolf Sharpe-difference tests (Table 4.1)                   ~1 h
%   econ       economic-interpretation analyses 1-3 (incl. Ledoit-Wolf tests)    ~20 min
%   verify     compare every regenerated CSV with results/ (numeric columns)
% Simulations are never run here; see README "Simulations (optional)".
% External inputs: data/<h>/df.csv and data/return_pairs/ (variance-swap return
% series), checked against data/SHA256SUMS.

order = {'data','empirical','cv','noncrisis','oos','effdim','lw','econ','verify'};
if nargin < 1 || isempty(stages), stages = setdiff(order, {'data','cv','lw'}, 'stable'); end
stages = cellstr(stages);
assert(all(ismember(stages, order)), 'Unknown stage. Valid: %s', strjoin(order, ', '));
root = fileparts(mfilename('fullpath'));
run(fullfile(root, 'drivers', 'setpath.m'));
final = fullfile(root, 'results');
if nargin < 2 || isempty(outRoot), outRoot = fullfile(root, 'results_replication'); end
assert(~strcmp(local_abs(outRoot), local_abs(final)), 'outRoot must differ from results/.');
if ~isfolder(outRoot), mkdir(outRoot); end
old = getenv('SDF_RESULTS_ROOT'); setenv('SDF_RESULTS_ROOT', local_abs(outRoot));
restore = onCleanup(@() setenv('SDF_RESULTS_ROOT', old));
local_check_inputs(root);
O = @(varargin) fullfile(results_root(), varargin{:});
H = {'quarterly','monthly','weekly','daily'};
V = table();

for s = order(ismember(order, stages))
    fprintf('\n=== stage: %s  (%s) ===\n', s{1}, char(datetime('now')));
    switch s{1}
        case 'data'
            run_forward_reconstruction();
            run_stage1_reconstruction();
        case {'empirical','cv'}
            m = 'eff_dim'; if strcmp(s{1}, 'cv'), m = 'cv'; end
            run_empirical_pipeline(H, true, m);          % resumes fits and shape-test checkpoints
            if strcmp(m, 'eff_dim')
                for h = H, plot_conditional_sdf_figures(h{1}); end   % figure curves (CSV + PNG)
            end
        case 'noncrisis'
            todo = H(~cellfun(@(h) isfile(O('empirical_noncrisis','eff_dim',h,[h '_noncrisis_returns.csv'])), H));
            if ~isempty(todo), run_noncrisis_effdim_fits(todo); end
        case 'oos'
            oos_setup();
            run_empirical_oos_attribution(H, struct('mode', 'validation'));   % resumes windows
            run_empirical_oos_attribution(H, struct('mode', 'validation', 'information_rule', 'python_reference'));
            run_oos_sensitivity_exclude_dates('daily', datetime(2023,10,19), struct('mode', 'validation'));
            if ~isfile(O('empirical_oos','eff_dim','tables','oos_performance.csv'))
                make_oos_tables(struct('sensitivity', {{{'daily', 'sensitivity_excl_20231019'}}}));
            end
        case 'effdim'
            oos_setup();
            if ~isfile(O('empirical_effdim_target','monthly','effdim_target_monthly.csv'))
                run_effdim_target_sensitivity('monthly');
            end
        case 'lw'
            if ~isfolder(O('inference','performance_sharpe','eff_dim_sb10')), run_lw_sharpe_inference('eff_dim'); end
        case 'econ'
            E = @(varargin) O('economic_interpretation','eff_dim',varargin{:});
            for h = H
                if ~isfile(E('exp1',h{1},[h{1} '_exp1_summary.csv'])), exp1_stageA(h{1}); end
                if ~strcmp(h{1},'quarterly') && ~isfile(E('exp1',h{1},[h{1} '_exp1_lw_summary.csv'])), exp1_stageB(h{1}); end
                if ~isfile(E('exp2',h{1},[h{1} '_exp2.mat'])), exp2_option_role(h{1}); end
            end
            if ~isfile(E('exp3','exp3_cross_maturity.mat')), exp3_cross_maturity(); end
        case 'verify'
            V = local_verify(results_root(), final);
    end
end
end

function V = local_verify(newRoot, final)
%% Compare every CSV regenerated in newRoot with its finalized copy in results/.
% Deterministic numeric columns must agree to 1e-8 (relative). Shape-test Monte Carlo
% columns are judged against Monte Carlo error: with a singular HAC covariance the
% eigen-factor used for the draws is not bitwise stable across runs, so p-values and
% critical values reproduce up to simulation noise (|dp| <= 4 SE of a difference of two
% nMC = 10000 estimates), W_T to 1e-5 and the near-zero omega_min_eig to 1e-6 of
% omega_max_eig; reject_* are reported as the number of changed decisions.
skip = {'fit_seconds','seconds','reused','n_reused','code_clean_at_run','code_hash_matches_run','all_ok'};
mc = {'p_value','critical_10pct','critical_5pct','critical_1pct','reject_10pct','reject_5pct', ...
    'reject_1pct','W_T','omega_min_eig','inference_condition_number','mc_n_valid','mc_n_failed'};
f = dir(fullfile(newRoot, '**', '*.csv'));
f = f(~contains({f.folder}, {'_scratch','windows','rejection_studies'}) & ~strcmp({f.name}, 'verification.csv'));
rows = {};
for k = 1:numel(f)
    rel = strrep(fullfile(f(k).folder, f(k).name), [newRoot filesep], '');
    ref = fullfile(final, rel);
    if ~isfile(ref), rows(end+1,:) = {rel, NaN, NaN, "no finalized copy"}; continue; end %#ok<AGROW>
    A = readtable(fullfile(newRoot, rel)); B = readtable(ref);
    if height(A) ~= height(B), rows(end+1,:) = {rel, Inf, NaN, "row count differs"}; continue; end %#ok<AGROW>
    vars = intersect(A.Properties.VariableNames, B.Properties.VariableNames, 'stable');
    vars = vars(cellfun(@(v) isnumeric(A.(v)) && isnumeric(B.(v)), vars) & ~ismember(vars, skip));
    isMC = ismember('p_value', vars) && ismember('W_T', vars);    % shape-test table
    d = 0; note = "";
    for v = vars
        a = double(A.(v{1})); b = double(B.(v{1}));
        if isMC && ismember(v{1}, mc), continue; end
        both = isfinite(a) & isfinite(b);
        assert(isequal(isfinite(a), isfinite(b)), 'NaN pattern differs in %s:%s', rel, v{1});
        d = max([d; abs(a(both) - b(both)) ./ max(1, abs(b(both)))]);
    end
    zmax = NaN;
    if isMC
        pa = A.p_value; pb = B.p_value;
        z = abs(pa - pb) ./ sqrt(2 * max(pb .* (1 - pb), 1e-4) / 1e4);
        zmax = max(z);
        wRel = max(abs(A.W_T - B.W_T) ./ max(1, abs(B.W_T)));
        eRel = max(abs(A.omega_min_eig - B.omega_min_eig) ./ B.omega_max_eig);
        nFlip = arrayfun(@(L) sum(A.(L{1}) ~= B.(L{1})), {'reject_10pct','reject_5pct','reject_1pct'});
        note = sprintf("MC: max|dp|/SE %.2f, W_T rel %.1e, decisions changed at 10/5/1%%: %d/%d/%d", ...
            zmax, wRel, nFlip);
        d = max([d, (wRel > 1e-5) + (eRel > 1e-6) + (zmax > 4)]);   % any MC breach fails the row
    end
    rows(end+1,:) = {rel, d, zmax, note}; %#ok<AGROW>
end
V = cell2table(rows, 'VariableNames', {'file','max_rel_diff','mc_max_z','note'});
V.ok = V.max_rel_diff <= 1e-8;
disp(V); fprintf('verify: %d of %d files agree.\n', sum(V.ok), height(V));
writetable(V, fullfile(newRoot, 'verification.csv'));
end

function local_check_inputs(root)
%% Hash the external inputs against data/SHA256SUMS.
L = splitlines(strtrim(fileread(fullfile(root, 'data', 'SHA256SUMS'))));
for k = 1:numel(L)
    p = regexp(L{k}, '^(\w{64})\s+(.+)$', 'tokens', 'once');
    f = fullfile(root, 'data', p{2});
    assert(isfile(f), 'Missing input %s (see data/README.md).', f);
    assert(strcmp(oos_sha256_file(f), p{1}), 'Input %s differs from data/SHA256SUMS.', f);
end
end

function h = oos_sha256_file(f)
fid = fopen(f, 'r'); c = onCleanup(@() fclose(fid));
h = oos_sha256(fread(fid, Inf, '*uint8'));
end

function p = local_abs(p)
f = java.io.File(p); if ~f.isAbsolute(), f = java.io.File(pwd, p); end
p = char(f.getCanonicalPath());
end
